class Solution { public:
    string bestHand(vector<int>& ranks, vector<char>& suits) {
        if(all_of(suits.begin(),suits.end(),[&](char c){return c==suits[0];}))return "Flush";
        int f[14]={};int mx=0;for(int x:ranks)mx=max(mx,++f[x]);
        if(mx>=3)return "Three of a Kind";
        if(mx>=2)return "Pair";
        return "High Card";
    }
};
